(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0003.js"] = [{"id":"glyph-kai-59ca","script":"kai","character":"姊","reading":"zǐ","description":"zǐ：姐姐～妹（a.姐姐和妹妹；b.同辈女朋友亲热的称呼）。～夫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姊"},{"id":"glyph-kai-59cb","script":"kai","character":"始","reading":"shǐ","description":"shǐ：(1)起头，最初，与终”相对开～。～终。～祖。～创。周而复～。\n(2)才，刚才方～。～悟（才觉悟到）。春蚕到死丝方尽，蜡炬成灰泪～干。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-始"},{"id":"glyph-kai-59d0","script":"kai","character":"姐","reading":"jiě","description":"jiě：(1)称同父母（或只同父、只同母）而比自己年纪大的女子～～。～夫。～弟。\n(2)对比自己年纪大的同辈女性的称呼表～。师～。大～（a.对一般年轻妇女的称呼；b.对排行最大的姐姐的称呼）。\n(3)对未婚女子的通称小～（旧时称上层社会未婚女子，现多用于交际场合）。小大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姐"},{"id":"glyph-kai-59d1","script":"kai","character":"姑","reading":"gū","description":"gū：(1)称父亲的姐妹～～。～父。～表（一家的父亲和另一家的母亲是兄妹或姐弟的亲戚关系，如～～兄弟”）。\n(2)丈夫的姊妹小～子。～嫂。\n(3)旧时妻称夫的母亲翁～。舅～。\n(4)少女，亦作妇女的通称～娘（a.未婚少女，娘”读轻声；b.姑母）。道～。尼～。\n(5)暂且，苟且～且。～息。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姑"},{"id":"glyph-kai-59d3","script":"kai","character":"姓","reading":"xìng","description":"xìng：(1)表明家族的字～氏。～名。贵～（询问对方姓氏的敬辞）。\n(2)平民万～。老百～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姓"},{"id":"glyph-kai-59d4","script":"kai","character":"委","reading":"wěi；wēi","description":"wěi：(1)任，派，把事交给人办～托。～派。～任。～员。～以重任。\n(2)抛弃，舍弃～弃。～之于地。\n(3)推托，卸推～。～罪。\n(4)曲折，弯转～曲。～婉。～屈。\n(5)积聚～积。\n(6)末、尾原～。穷源意～（追究事物本原及其发展）。\n(7)确实～实。\n(8)无精打采，不振作～顿。～靡。\nwēi：〔～蛇（yí）〕a.敷衍，应付；b.同逶迤”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-委"},{"id":"glyph-kai-59da","script":"kai","character":"姚","reading":"yáo","description":"yáo：(1)美好的样子～冶（妖艳）。\n(2)姓。\n(3)古同遥”，远。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姚"},{"id":"glyph-kai-59dc","script":"kai","character":"姜","reading":"jiāng","description":"jiāng：(1)多年生草本植物，地下茎黄色，味辣，可供调味用，亦可入药生～。～汤。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姜"},{"id":"glyph-kai-59e5","script":"kai","character":"姥","reading":"lǎo；mǔ","description":"mǔ：年老的妇女。\nlǎo：〔～～〕a.称外祖母，亦为对老妇人的敬称；b.旧时称接生的妇女。均亦作老老”（后一个姥”、老”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姥"},{"id":"glyph-kai-59e8","script":"kai","character":"姨","reading":"yí","description":"yí：(1)称母亲的姊妹～母。～妈。～父。\n(2)妻的姊妹大～子。小～子。\n(3)妾～太太。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姨"},{"id":"glyph-kai-59fb","script":"kai","character":"姻","reading":"yīn","description":"yīn：(1)男女嫁娶婚～。～缘。\n(2)由婚姻关系而结成的亲属～亲。联～。\n(3)较间接的亲戚关系～故。～旧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姻"},{"id":"glyph-kai-59ff","script":"kai","character":"姿","reading":"zī","description":"zī：(1)面貌，容貌～容。丰～。～色。天～。\n(2)形态，样子～态。～势。舞～。风～。英～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-姿"},{"id":"glyph-kai-5a01","script":"kai","character":"威","reading":"wēi","description":"wēi：(1)表现出来使人敬畏的气魄～力。～风。权～。\n(2)凭借力量或势力～胁。～慑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-威"},{"id":"glyph-kai-5a03","script":"kai","character":"娃","reading":"wá","description":"wá：(1)小孩子～子。胖～～。\n(2)旧称美女娇～。\n(3)某些幼小的动物猪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娃"},{"id":"glyph-kai-5a04","script":"kai","character":"娄","reading":"lóu","description":"物体中空的\n收敛\n二十八宿之一,西方白虎七宿的第二宿。有白羊座α、β、γ星三颗\n母猪\n通塿”。小土丘\n假借为屡”\n娄lǘ 1.牵，曳。\n娄lǚ 1.拴系。 2.卷曲。参见\"娄络\"。\n娄lǒu 1.见\"部娄\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娄"},{"id":"glyph-kai-5a07","script":"kai","character":"娇","reading":"jiāo","description":"⒈美好可爱万紫千红分外～。\n⒉柔嫩，怕苦怕累～嫩。～气。\n⒊宠爱～惯。～生惯养。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娇"},{"id":"glyph-kai-5a18","script":"kai","character":"娘","reading":"niáng","description":"niáng：(1)母亲～亲。～家。爹～。\n(2)对年轻女子的称呼～子。姑～。娇～。新～。\n(3)称长一辈或年长的已婚妇女大～。婶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娘"},{"id":"glyph-kai-5a1c","script":"kai","character":"娜","reading":"nà；nuó","description":"nà：女子人名用字及译音字。\nnuó：〔婀～〕见婀”。\n〔袅～〕见袅”。\n〔～～〕轻柔的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娜"},{"id":"glyph-kai-5a1f","script":"kai","character":"娟","reading":"juān","description":"juān：秀丽，美好～丽。～秀。～～（秀美的样子）。～媚。婵～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娟"},{"id":"glyph-kai-5a25","script":"kai","character":"娥","reading":"é","description":"é：(1)女子姿容美好～眉。～～（美好的样子）。\n(2)美女娇～。宫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娥"},{"id":"glyph-kai-5a31","script":"kai","character":"娱","reading":"yú","description":"yú：快乐或使人快乐～乐（lè）。～老（欢度晚年）。～亲（使父母快乐）。～悦。自～。～情陶性。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娱"},{"id":"glyph-kai-5a36","script":"kai","character":"娶","reading":"qǔ","description":"qǔ：把女子接过来成亲～亲。～妻。迎～。嫁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-娶"},{"id":"glyph-kai-5a46","script":"kai","character":"婆","reading":"pó","description":"pó：(1)年老的妇女老太～。苦口～心。\n(2)丈夫的母亲公～。～媳。～家。～～。\n(3)称长两辈的亲属妇女姑～。姨～。外～。\n(4)方言，泛指已婚的青年妇女，亦称妻子～娘。～姨。\n(5)旧时指从事某些职业的妇女媒～。收生～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婆"},{"id":"glyph-kai-5a49","script":"kai","character":"婉","reading":"wǎn","description":"wǎn：(1)和顺，（说话）曲折含蓄～顺。～转（zhuǎn）（亦作宛转”）。委～。～辞。\n(2)美好，柔美～丽。～约。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婉"},{"id":"glyph-kai-5a5a","script":"kai","character":"婚","reading":"hūn","description":"hūn：男女结为夫妇结～。新～。已～。～姻。～约。～礼。～变。～娶。～外恋。离～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婚"},{"id":"glyph-kai-5a6a","script":"kai","character":"婪","reading":"lán","description":"lán：贪爱财物贪～。～酣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婪"},{"id":"glyph-kai-5a74","script":"kai","character":"婴","reading":"yīng","description":"初生的女孩\n亦泛指初生儿\n系到颈上;戴\n辟之,是犹使处女婴宝珠、\n⒈初生的小孩～儿。女～。\n⒊碰，触犯国富民强，敌国不敢～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婴"},{"id":"glyph-kai-5a76","script":"kai","character":"婶","reading":"shěn","description":"叔母。父亲弟弟的妻子\n称呼与父母同辈而年龄较小的已婚妇女\n兄、嫂称弟之妻\n⒈叔叔的妻子～娘。么～子。\n⒉跟自己母亲同辈而年龄较小的已婚妇女张～。李二～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婶"},{"id":"glyph-kai-5a7f","script":"kai","character":"婿","reading":"xù","description":"xù：(1)丈夫夫～。\n(2)女儿、妹妹及其他晚辈的丈夫女～。妹～。侄～。甥～。贤～。翁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-婿"},{"id":"glyph-kai-5a92","script":"kai","character":"媒","reading":"méi","description":"méi：(1)撮合男女婚事的人～人。～妁（旧指婚姻介绍人）。～婆。\n(2)使双方发生关系的人或事物～介。～体。触～。传～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媒"},{"id":"glyph-kai-5a9a","script":"kai","character":"媚","reading":"mèi","description":"mèi：(1)谄，逢迎～外。～世（迎合世俗）。～眼。～惑。～态。谄～。献～。奴颜～骨。\n(2)美好，可爱～景。明～。秀～。妩～。娇～。\n(3)喜爱我既～君姿，君亦悦我颜。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媚"},{"id":"glyph-kai-5ab3","script":"kai","character":"媳","reading":"xí","description":"xí：子、弟及其他晚辈的妻子儿～。弟～。侄～。孙～。～妇儿（fur）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-媳"},{"id":"glyph-kai-5ac1","script":"kai","character":"嫁","reading":"jià","description":"jià：(1)女子结婚出～。～娶。再～。～奁。～妆。\n(2)把祸害、怨恨推到别人身上～怨。～祸于人。～非（委过于人）。转～。\n〔～接〕把不同品种的两种植物接在一起，让它变种，达到提早结果、增加抗性、提高品种质量等目的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫁"},{"id":"glyph-kai-5ac2","script":"kai","character":"嫂","reading":"sǎo","description":"sǎo：(1)哥哥的妻子～～。～子。兄～。\n(2)泛称年岁不大的已婚妇女大～。～夫人（对朋友妻子的尊称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫂"},{"id":"glyph-kai-5ac9","script":"kai","character":"嫉","reading":"jí；jī","description":"jī：(1)因别人比自己好而怨恨～妒。～恨。～羡。\n(2)憎恨～恶如仇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫉"},{"id":"glyph-kai-5acc","script":"kai","character":"嫌","reading":"xián","description":"xián：(1)可疑之点～疑。避～。涉～。\n(2)厌恶，不满意～恶（wù）。～弃。讨人～。\n(3)怨尽释前～。～隙（由猜疑而形成的仇怨）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫌"},{"id":"glyph-kai-5ae9","script":"kai","character":"嫩","reading":"nèn","description":"nèn：(1)初生而柔弱娇～。～芽。\n(2)（颜色）淡；浅～绿。～黄。\n(3)幼稚；不老练稚～。～手。\n(4)轻；微～寒清晓。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嫩"},{"id":"glyph-kai-5b50","script":"kai","character":"子","reading":"zǐ","description":"zǐ：(1)古代指儿女，现专指儿子～女。～孙。～嗣。～弟（后辈人，年轻人）。\n(2)植物的果实、种子菜～。瓜～儿。～实。\n(3)动物的卵鱼～。蚕～。\n(4)幼小的，小的～鸡。～畜。～城。\n(5)小而硬的颗粒状的东西～弹（dàn）。棋～儿。\n(6)与母”相对～金（利息）。～母扣。～音（辅音）。\n(7)对人的称呼男～。妻～。士～（读书人）。舟～（船夫）。才～。\n(8)古代对人的尊称；称老师或称有道德、有学问的人孔～。先秦诸～。\n(9)地支的第一位，属鼠～丑寅卯（喻有条不紊的层次或事物的条理）。\n(10)用于计时～时（夜十一点至一点）。～夜（深夜）。\n(11)封建制度五等爵位的第四等～爵。\n(12)附加在名词、动词、形容词后，具有名词性（读轻声）旗～。乱～。胖～。\n(13)个别量词后缀（读轻声）敲了两下～门。\n(14)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-子"},{"id":"glyph-kai-5b54","script":"kai","character":"孔","reading":"kǒng","description":"kǒng：(1)小洞，窟窿～穴。～眼。～洞。～方兄（指钱，因旧时的铜钱有方形的孔，恢谐含鄙意）。\n(2)很～急。～武有力。\n(3)量词，用于窑洞一～土窑。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孔"},{"id":"glyph-kai-5b55","script":"kai","character":"孕","reading":"yùn","description":"yùn：胎，怀胎怀～。～妇。～育（怀胎生育，喻既存事物中酝酿着新事物）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孕"},{"id":"glyph-kai-5b57","script":"kai","character":"字","reading":"zì","description":"zì：(1)用来记录语言的符号文～『～。～符。～母。～典。～句。～里行（háng）间。～斟句酌。\n(2)文字的不同形式，书法的派别草～。篆～。颜～。柳～。欧～。赵～。\n(3)书法的作品～画。～幅。\n(4)字的音～正腔圆。\n(5)人的别名，亦称表～”，现多称号”；商店的名称，亦称～号”。\n(6)合同，契约～据。\n(7)旧时称女子出嫁待～闺中。\n(8)生子，乳，爱～乳（生育）。～孕（怀孕）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-字"},{"id":"glyph-kai-5b58","script":"kai","character":"存","reading":"cún","description":"cún：(1)东西在那里，人活着～在。～亡。生～。\n(2)保留，留下保～。留～。～照。～疑。去伪～真。\n(3)寄放寄～。\n(4)停聚～水。\n(5)怀有，怀着～心。不～任何奢望。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-存"},{"id":"glyph-kai-5b59","script":"kai","character":"孙","reading":"sūn","description":"跟孙子同辈的同性或异性亲属\n⒈儿子的子女～子。～女。\n⒉孙子以后各代曾～。玄～。子～后代。\n⒊跟孙子同辈的亲属外～子。侄～女。\n⒋植物再生或孳生的稻～。～竹。\n⒌〈古〉通\"逊\"。逃。\n孙xùn 1.谦顺;恭顺。 2.逃遁;流亡。 3.退出﹑让出帝位或某职位。 4.差，比不上。\n孙xún 1.见\"孙子\"﹑\"孙孟\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孙"},{"id":"glyph-kai-5b5d","script":"kai","character":"孝","reading":"xiào","description":"xiào：(1)对父母尽心奉养并顺从～敬。～廉（ａ．中国汉代盐官吏的科目之一，孝”指孝子；廉”指廉洁的人；ｂ．中国明、清两代对举人的称呼）。～道。～子贤孙。\n(2)居丧的事守～。吊～。\n(3)丧服戴～。～衣。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孝"},{"id":"glyph-kai-5b5f","script":"kai","character":"孟","reading":"mèng","description":"mèng：(1)兄弟姊妹排行最大的～兄。～女（长女）。～孙。\n(2)农历四季中月份在开头的（其它两个月依次为仲、季）～春（农历正月）。\n(3)猛然不及思考，冒冒失失～行。～浪。\n(4)勉力～晋（勉力求进）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孟"},{"id":"glyph-kai-5b63","script":"kai","character":"季","reading":"jì","description":"jì：(1)兄弟排行次序最小的～弟（小弟）。～父（小叔叔）。\n(2)末了～世。～春（春季末一月）。明～（明代末年）。～军（体育运动竞赛的第三名）。\n(3)一年的四分之一一年分春夏秋冬四～。～度。～风。\n(4)一段时间～节。～候。～相（xiàng）（某个地区在某个季节的自然景象）。雨～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-季"},{"id":"glyph-kai-5b64","script":"kai","character":"孤","reading":"gū","description":"gū：(1)幼年死去父亲或父母双亡～儿。遗～。托～。～寡鳏独（孤儿，寡妇，无妻或丧妻的人，年老无子女的人）。\n(2)单独～单。～独。～立。～僻。～傲。～茕（单独无依然）。～介。～身。～危。～芳自赏。～苦伶仃。～掌难鸣。～云野鹤（喻闲逸逍遥的人）。\n(3)古代帝王的自称～家。～王。\n(4)古同辜”，辜负。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孤"},{"id":"glyph-kai-5b66","script":"kai","character":"学","reading":"xué","description":"⒈指学习～工。～农。～医。～哲学。～而不厌。～习科学知识。\n⒉模仿边看边～。照字帖～写字。鹦鹉～舌。\n⒊指学问。\n①反映客观事物的系统知识这是一门新兴的～问。\n②知识求～。博～多才。\n③学和问勤～多问。\n⒋指学识，学术上的知识和修养她的～识渊博。\n⒌指学校，集体培养人才的地方小～。中～。大～。\n⒍指学科，分门别类的有系统的知识医～。化～。生物～。经济～。\n①在学校学习的人。\n②向前辈或向能者学习的人。\n③求学者谦称自己。\n①〈古〉官名翰林～士。\n②旧称学者文人～士。\n③学位名在硕士之下。\n学xiào 1.教导。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-学"},{"id":"glyph-kai-5b69","script":"kai","character":"孩","reading":"hái","description":"hái：儿童，引申为子女男～儿。～童。～提（指幼儿时期）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孩"},{"id":"glyph-kai-5b75","script":"kai","character":"孵","reading":"fū","description":"fū：鸟类伏在卵上（亦指用人工的方法），使卵内的胚胎发育成雏鸟～化。～育。～小鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孵"},{"id":"glyph-kai-5b7d","script":"kai","character":"孽","reading":"niè","description":"niè：(1)恶因，恶事，邪恶～臣（奸佞之臣）。～种（zhǒng）。～根。～海。～障（ａ．长辈骂后辈为不肖子弟的话；ｂ．佛教指妨碍修行的种种罪恶。均亦称业障”）。作～（做伤天害理的事）。罪～（罪恶）。造～。\n(2)奴隶社会、封建社会多妻制下指妾及其子女～妾。～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-孽"},{"id":"glyph-kai-5b81","script":"kai","character":"宁","reading":"níng","description":"⒈安定，平安～静。康～。既安且～。\n⒉南京市的简称。\n⒈情愿～可。～愿。～缺毋滥。～死不屈。\n⒊文言副词。岂，难道王侯将相～有种乎？\n宁zhù 1.古代宫室门屏之间。 2.同\"贮\"。贮藏;积聚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宁"},{"id":"glyph-kai-5b83","script":"kai","character":"它","reading":"tā","description":"tā：代词，称人以外的事物～们。其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-它"},{"id":"glyph-kai-5b85","script":"kai","character":"宅","reading":"zhái","description":"zhái：(1)住所，房子（多指较大的）住～。内～（指住宅内女眷的住处）。～门。～邸。～第。\n(2)葬地，墓穴～兆（坟墓的四界）。\n(3)居住～心仁厚（居心仁义厚道）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宅"},{"id":"glyph-kai-5b87","script":"kai","character":"宇","reading":"yǔ","description":"yǔ：(1)屋檐，泛指房屋～下（屋檐之下，喻在他人庇护之下）。屋～。庙～。～宙（ａ．屋檐和栋梁；ｂ．空间与时间；ｃ．天地）。\n(2)国土，疆土故～。\n(3)整个空间世界～内（指天下）。玉～。～航。\n(4)风度，仪表眉～（指人的样子，仪表）。器～轩昂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宇"},{"id":"glyph-kai-5b88","script":"kai","character":"守","reading":"shǒu","description":"shǒu：(1)保持，卫护～成（在事业上保持前人的成就）。～御。～身（爱护自身，保持自己的品节）。～节。～恒。～望相助。墨～成规。\n(2)看管看～。～护。\n(3)在一个地方不动～株待兔。留～。\n(4)遵照遵～。～法。～时。\n(5)维持原状，不想改变保～。因循～旧。\n(6)呆在一起厮～。\n(7)节操操～。\n(8)靠近，依傍～着水的地方，可多种稻子。\n(9)古代官名太～。～祧（中国周代掌管祭祀宗庙的官）。～刺（太守，刺史）。～令（指太守、刺史、县令等地方官）。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-守"},{"id":"glyph-kai-5b89","script":"kai","character":"安","reading":"ān","description":"ān：(1)平静，稳定～定。～心。～宁。～稳。～闲。～身立命。～邦定国。\n(2)使平静，使安定（多指心情）～民。～慰。～抚。\n(3)对生活工作等感觉满足合适心～。～之若素（遇到不顺利情况或反常现象像平常一样对待，毫不在意）。\n(4)没有危险，不受威协平～。转危为～。\n(5)装设～置。～家立业。\n(6)存着，怀着（某种念头，多指不好的）他～的什么心？\n(7)疑问词，哪里～能如此？\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-安"},{"id":"glyph-kai-5b8b","script":"kai","character":"宋","reading":"sòng","description":"sòng：(1)中国周代诸侯国名，在今河南省商丘市一带。\n(2)中国朝代名南～。～代。～词。\n(3)响度单位，一宋约相当于人耳刚能听到的声音响度的一千倍，等于1000毫宋。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宋"},{"id":"glyph-kai-5b8c","script":"kai","character":"完","reading":"wán","description":"wán：(1)全～备。～全。～整。～善。～好。～璧归赵。覆巢无～卵。\n(2)尽，无用～了。煤烧～了。\n(3)做成，了结～毕。～成。～结。\n(4)交纳～粮。～税。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-完"},{"id":"glyph-kai-5b8f","script":"kai","character":"宏","reading":"hóng","description":"hóng：(1)广大，博大～大。～伟。～图。～愿。～论。～丽。～亮。～观。宽～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宏"},{"id":"glyph-kai-5b97","script":"kai","character":"宗","reading":"zōng","description":"zōng：(1)家族的上辈，民族的祖先祖～。～庙。～祠。\n(2)家族～法（封建社会以家族为中心，按制统远近区别亲疏的制度）。～族。～室（帝王的宗族）。～兄。\n(3)派别～派。禅～（佛教的一派）。\n(4)主要的目的和意图～旨。开～明义。\n(5)尊奉～仰。\n(6)为众人所师法的人物～师。\n(7)量词，指件或批一～心事。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宗"},{"id":"glyph-kai-5b98","script":"kai","character":"官","reading":"guān","description":"guān：(1)在政府担任职务的人～吏。～僚。～邸。～腔。～署。～厅。～爵。\n(2)属于国家的或公家的～办。～费。～方。～府。\n(3)生物体上有特定机能的部分感～。器～。五～。～能。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-官"},{"id":"glyph-kai-5b99","script":"kai","character":"宙","reading":"zhòu","description":"zhòu：古往今来所有的时间宇～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宙"},{"id":"glyph-kai-5b9a","script":"kai","character":"定","reading":"dìng","description":"dìng：(1)不动的，不变的～额。～价。～律。～论。～期。～型。～义。～都（dū）。～稿。～数（shù）（ａ．规定数额；ｂ．指天命；ｃ．规定的数额）。断～。规～。鉴～。\n(2)使不变动～案。～罪。决～。确～。\n(3)平安，平靖（多指局势）大局已～。\n(4)镇静，安稳（多指情绪）心神不～。\n(5)确凿，必然的必～。镇～。\n(6)预先约妥～计。～情。～货。～做。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-定"},{"id":"glyph-kai-5b9b","script":"kai","character":"宛","reading":"wǎn；yuān","description":"wǎn：(1)曲折委～。～妙（声音婉转动听）。～转（zhuǎn）（ａ．辗转；ｂ．同婉转”）。\n(2)仿佛～然。～如。～若（仿佛，好像）。\n(3)姓。\nyuān：〔大～〕古代西域国名，在中亚西亚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宛"},{"id":"glyph-kai-5b9c","script":"kai","character":"宜","reading":"yí","description":"yí：(1)适合，适当～人。～于∠～。权～。适～。相～。\n(2)应该，应当事不～迟。\n(3)当然，无怪～其无往而不利也。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宜"},{"id":"glyph-kai-5b9d","script":"kai","character":"宝","reading":"bǎo","description":"①珍贵的东西粮食是个～，谁都离不了。\n②珍贵的～刀。\n③旧时的一种赌具。\n④旧时用于称别人的家眷、铺子等的敬辞～眷、～号。\n【宝船】明代滞下西洋时使用的海船的名称。据有关资料，最大的船长158米，宽56米。\n【宝石】硬度较大，色泽美丽，受到大气和化学药品的作用不起变化，产量稀少而极为贵重的矿物，统称为宝石。如金刚石、刚玉、黄玉、硬玉、绿柱石等。\n【宝惜】珍惜。\n【宝座】\n①帝王或神佛的座位。\n②借指某一职位或荣誉冠军～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宝"},{"id":"glyph-kai-5b9e","script":"kai","character":"实","reading":"shí","description":"真实;诚实\n夫图画,\n⒈满，充满～心铅球。～足岁数。仓库充～。\n⒉种子，果子果～。\n⒊真，诚恳，不狡猾真～。诚～。老～。说～话。\n⒋客观存在的～事。～际。～力。～况。事～。\n⒌的确确～。\n⒍用于加强语气～难从命。\n⒎施，执行，推行～施。～行。\"\n①真，的确～在对。\n②不虚假，不马虎他干活很～在。\n③其实，实际他说懂了，～在是哄骗人。\n①客观的真实情况。也指实践联系～际。\n②具体的～际效果。\n①人们改造自然和改造社会的活动。\n②实行及履行自己的主张或诺言。\n①为了检验某种科学理论或假设而进行的观察和研究活动。\n②指实验的工作。\n实zhì 1.到达。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-实"},{"id":"glyph-kai-5ba0","script":"kai","character":"宠","reading":"chǒng","description":"宠爱\n【宠爱】过分喜爱；偏爱。\n【宠辱不惊】无论受宠或是受辱都无动于衷。形容把荣辱得失置之度外。\n【宠辱若惊】受宠受辱都感到不安。形容患得患失。\n【宠幸】旧时指帝王对后妃、臣下宠爱，后泛指地位高的人对地位低的人的宠爱。\n⒈偏爱，溺爱～爱。\n⒉荣耀～辱不惊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宠"},{"id":"glyph-kai-5ba1","script":"kai","character":"审","reading":"shěn","description":"知道,知悉\n⒈周密，详细～慎。精～。用意详～。〈引〉细思，细查，推究，评定，弄明白～查。～核。～稿。～议。～定。～时度势。\n⒊知道，明白，也作\"谂\"～悉。当局者迷，旁观者～。\n⒋确实，果然～如其言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-审"},{"id":"glyph-kai-5ba2","script":"kai","character":"客","reading":"kè","description":"kè：(1)外来的（人），与主”相对～人。宾～。会～。不速之～。～气。～卿。\n(2)外出或寄居，迁居外地的（人）旅～。～居。～籍。～死。\n(3)服务行业的服务对象顾～。乘～。～流量。\n(4)指奔走各地从事某种活动的人说～。政～。侠～。\n(5)在人类意识外独立存在的～观。～体。\n(6)量词，用于论份儿出售的食品、饮料一～冰淇淋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-客"},{"id":"glyph-kai-5ba3","script":"kai","character":"宣","reading":"xuān","description":"xuān：(1)公开说出，散布～讲。～传。～战。～称。～言。～叙调。心照不～。\n(2)疏导～泄。\n(3)古代帝王的大室。\n(4)皇帝命令或传达皇帝的命令～付。～召（皇帝召见）。～诏（传旨）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宣"},{"id":"glyph-kai-5ba4","script":"kai","character":"室","reading":"shì","description":"shì：(1)屋子，房间，亦指家居～。教～。会客～。温～。引狼入～。\n(2)家，家族皇～。女有家，男有～。\n(3)机关团体内部的工作单位档案～。\n(4)古指妻子（亦指为子娶妻或以女嫁人）妻～。继～。\n(5)刀剑的鞘。\n(6)墓穴。\n(7)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-室"},{"id":"glyph-kai-5ba6","script":"kai","character":"宦","reading":"huàn","description":"huàn：(1)官，做官官～。仕～。～海。～游。\n(2)阉人，太监～官。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宦"},{"id":"glyph-kai-5baa","script":"kai","character":"宪","reading":"xiàn","description":"喜乐的样子\n法令\n宪法的略称\n⒈法令～章。布～。\n⒉效法，摹仿。\n⒊指宪法立～。\n定其它法律的根据。\n宪xiǎn 1.明显。参见\"宪宪\"。 2.犹皇。旧时对先人的美称。参见\"宪考\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宪"},{"id":"glyph-kai-5bab","script":"kai","character":"宫","reading":"gōng","description":"gōng：(1)房屋（封建时代专指帝王的住所）～室。～廷。～殿。～观（guàn）（ａ．供帝王游乐的离宫；ｂ．道教的庙宇）。～禁。～苑。～刑。\n(2)神话中神仙居住的房屋天～。龙～。蟾～。\n(3)庙宇的名称雍和～。\n(4)一些文化娱乐场所少年～。文化～。\n(5)天文上黄道分为十二宫，每一宫三十度。\n(6)中国古代五音之一，相当于简谱1”。\n(7)指子宫”（妇女生殖器官）。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宫"},{"id":"glyph-kai-5bb0","script":"kai","character":"宰","reading":"zǎi","description":"zǎi：(1)杀牲畜～杀。屠～。～牲节（亦称古尔邦节”、牺牲节”）。\n(2)借指商贩用狡诈的手段使顾客在经济上受到损害（有的地区称斩”）。\n(3)古代官名～相（xiàng）。～辅。太～。～官。\n(4)主管、主持主～。～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宰"},{"id":"glyph-kai-5bb3","script":"kai","character":"害","reading":"hài","description":"hài：(1)有损的，与益”相对～虫。～鸟。\n(2)引起灾难的人或事物，坏处～处。祸～。灾～。为民除～。\n(3)使受损伤～人。损～。伤～。危～。\n(4)发生疾病～眼。\n(5)心理上发生不安定情绪～羞。～怕。\n(6)杀死杀～。遇～。\n(7)妒忌上官大夫与之同列，争宠而心～其能”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-害"},{"id":"glyph-kai-5bb4","script":"kai","character":"宴","reading":"yàn","description":"yàn：(1)以酒饭款待宾客～客。～饮。～席。\n(2)聚会在一起吃酒饭～会。～集。\n(3)酒席设～。国～。盛（shéng）～。\n(4)乐（lè），安闲～娱。～嬉。～乐（yuè）。～居。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宴"},{"id":"glyph-kai-5bb5","script":"kai","character":"宵","reading":"xiāo","description":"xiāo：夜通～达旦。春～。～夜。～禁。～衣旰食（天不亮就起来，天黑了才吃饭，形容勤于政务）。～遁。元～。夜～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宵"},{"id":"glyph-kai-5bb6","script":"kai","character":"家","reading":"jiā","description":"jiā：(1)共同生活的眷属和他们所住的地方～庭。～眷。～长（zhǎng）。～园。～谱。～塾。～乡。～风。～训。～规。～喻户晓。如数～珍。\n(2)家庭所在的地方回～。老～。安～。\n(3)居住可以～焉”。\n(4)对人称自己的尊长、亲属～祖。～父。～翁。～母。～慈。\n(5)家里养的，不是野生的～畜。～禽。\n(6)经营某种行业的人家或有某种身份的人家酒～。农～。\n(7)掌握某种专门学识或有丰富实践经验及从事某种专门活动的人专～。行（háng）～。作～。科学～。\n(8)学术流派儒～。法～。道～。墨～。纵横～。诸子百～。\n(9)量词，用于计算家庭或企业一～人家。\n(10)姓。\n野；\nji：(1)词尾，指一类的人老人～。\n(2)用在男人的名字或排行后面，指他的妻水生～","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-家"},{"id":"glyph-kai-5bb9","script":"kai","character":"容","reading":"róng","description":"róng：(1)包含，盛（chéng）～器。～量（liàng）。～积。～纳。无地自～。\n(2)对人度量大～忍。宽～。\n(3)让，允许～让。不～人说话。\n(4)相貌，仪表，景象，状态～止。～颜。～光。～貌。仪～。军～。市～。阵～。姿～。\n(5)或许，也许～或。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-容"},{"id":"glyph-kai-5bbd","script":"kai","character":"宽","reading":"kuān","description":"广阔;面积大。与狭”相对\n横的距离大\n度量宽宏;宽厚\n宽而栗\n⒈阔大，跟\"窄\"相对～阔。～敞。～广。～银幕。\n⒉松缓，放松～心。放～。〈引〉\n①脱去，解除请～了风衣。\n②伸延～限三天。\n③宽大～猛相济。处理从～。\n⒊富裕～裕。～绰。\n⒋度量大～宏大量。～大为怀。\n⒌物体横的距离～度。三尺～的布。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宽"},{"id":"glyph-kai-5bbe","script":"kai","character":"宾","reading":"bīn","description":"诸侯、诸伯、诸子、诸男之相为宾也。诸公之臣相为国客,是散文宾客通称,对称则宾尊而客卑,\n②客人贵～。\n③姓。\n【宾白】道白。古典戏曲用语。\n【宾词】一个命题的三个部分之一，表示思考对象的属性。如'竹子是植物'中的'植物'。又叫谓项。\n【宾服】服从；佩服。\n【宾格】屈折语中一种格的形式，表示该词是及物动词的宾语。如英语的him、me等。\n【宾客图】见【礼宾图】。\n【宾语补足语】补充说明宾语的成分。如'we call him james'中的'james'。\n【宾至如归】客人到这里如同回到自己家一样亲切。形容旅馆、饭店等招待客人很周到、热情。\n宾bìn 1.摈弃;排除;拒却。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宾"},{"id":"glyph-kai-5bbf","script":"kai","character":"宿","reading":"xiǔ；sù；xiù","description":"sù：(1)住，过夜，夜里睡觉住～。留～。露～。～舍（shè）。～营。\n(2)年老的，长久从事某种工作的～将（经验丰富的老将）。～儒。名～。\n(3)平素，素有的～愿。～志。～疾。～敌。～心。\n(4)隔夜的，隔年的～雨（昨夜的雨）。～根。～草。\n(5)姓。\nxiǔ：夜一～。两～。\nxiù：星座星～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-宿"},{"id":"glyph-kai-5bc2","script":"kai","character":"寂","reading":"jì","description":"jì：静，没有声音～静。～寞。孤～。～～。～灭。～默。～寥（寂静空旷）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寂"},{"id":"glyph-kai-5bc4","script":"kai","character":"寄","reading":"jì","description":"jì：(1)托付～托。～存。～情。～怀。～意。\n(2)依靠，依附～居。～食。～生虫。\n(3)托人传送，特指由邮局传递～信。～钱。\n(4)认的亲属～父。～母。～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寄"},{"id":"glyph-kai-5bc5","script":"kai","character":"寅","reading":"yín","description":"yín：(1)地支的第三位，属虎～吃卯粮（喻入不敷出）。\n(2)用于计时～时（夜三点至五点）。\n(3)敬～钱（恭敬地送）。～畏（敬畏）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寅"},{"id":"glyph-kai-5bc6","script":"kai","character":"密","reading":"mì","description":"mì：(1)稠，空隙小，与稀”、疏”相对紧～。稠～。茂～。严～。～封。～布。～集。～匝匝。～锣紧鼓（喻正式活动前的积极而紧张的准备，亦作紧锣密鼓”）。\n(2)关系近，感情好～友。～亲。\n(3)不公开，不公开的事物秘～。保～。～谋。～电。～报。～使。～信。～诏。～旨。～探。\n(4)精致，细致精～。细～。致～。～实（细密结实）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-密"},{"id":"glyph-kai-5bc7","script":"kai","character":"寇","reading":"kòu","description":"kòu：(1)盗匪，侵略者，亦指敌人盗～。贼～。\n(2)侵略者来侵犯～边。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寇"},{"id":"glyph-kai-5bcc","script":"kai","character":"富","reading":"fù","description":"fù：(1)财产、财物多～有。～足。～饶。～庶。～裕。～强。～豪。财～。～国强兵。\n(2)充裕，充足～余。～态。～丽堂皇。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-富"},{"id":"glyph-kai-5bd2","script":"kai","character":"寒","reading":"hán","description":"hán：(1)冷，与暑”相对～冬。～色。～衣。～冽。～带。～战。～噤。～食（节名，在清明前一天。古人从这一天起不生火做饭，也有的地区把清明当作寒食”）。～喧。～来暑往。唇亡齿～。\n(2)害怕～心。\n(3)穷困，有时用作谦辞～门。～伧。～舍。～窗（喻艰苦的学习环境）。～酸。～士（旧指贫穷的读书人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寒"},{"id":"glyph-kai-5bd3","script":"kai","character":"寓","reading":"yù","description":"yù：(1)原指寄居，后泛指居住～公（古代指寄居他国的官僚贵族；后泛指失势寄居他乡的地主绅士等人）。～居。～所。～舍。～邸。\n(2)住的地方公～。客～。\n(3)寄托寄～。～目（过目）。～言（a.有所寄托的话；b.用来说明某个道理的小故事）。～意（语言文字中所寄托或暗含的意思）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寓"},{"id":"glyph-kai-5bdd","script":"kai","character":"寝","reading":"qǐn","description":"⒈卧，睡觉就～。废～忘食。〈喻〉横卧的～石。\n⒉卧室～室。正～。内～。\n⒊卧病～疾。～病。\n⒋息，止～兵。其事遂～。\n⒌相貌丑陋貌～陋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寝"},{"id":"glyph-kai-5bde","script":"kai","character":"寞","reading":"mò","description":"mò：寂静，清静寂～。～～。～然。落～。冷～。孤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寞"},{"id":"glyph-kai-5bdf","script":"kai","character":"察","reading":"chá","description":"chá：仔细看，调查研究～看。～核。观～。考～（a.实地观察调查，如科学～～”；b.细致深刻地观察，如科学研究要勤于～～和思考”）。～觉。～访。～勘。～探。明～秋毫（秋毫”指秋天鸟兽身上新长的细毛，喻为人精明，任何小问题都看得清楚）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-察"},{"id":"glyph-kai-5be1","script":"kai","character":"寡","reading":"guǎ","description":"guǎ：(1)少，缺少～薄。～恩。～陋。～趣。优柔～断。～不敌众。孤陋～闻。～廉鲜（xiǎn）耻（不廉洁，不知耻）。清心～欲。\n(2)淡而无味～味。清汤～水。\n(3)妇女死了丈夫～妇。～母。～居。守～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寡"},{"id":"glyph-kai-5be5","script":"kai","character":"寥","reading":"liáo","description":"liáo：(1)稀少～～无几。～落（稀少，冷落，如疏星～～”）。～若晨星。\n(2)静寂，空虚寂～。～廓（高远空旷）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寥"},{"id":"glyph-kai-5be8","script":"kai","character":"寨","reading":"zhai；zhài","description":"zhài：(1)防守用的栅栏～子。鹿～（军事上常用的一种障碍物，古时多用削尖的竹木或枝杈，现多用铁蒺藜等做成）。\n(2)旧时驻兵的营地营～。山～。水～。安营扎～。～主。\n(3)村庄村～。苗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寨"},{"id":"glyph-kai-5bf8","script":"kai","character":"寸","reading":"cùn","description":"cùn：(1)中国市制长度单位，一尺的十分之一尺～。\n(2)短小～土。～阴（日影移动一寸的时间）。～心。～步难行。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寸"},{"id":"glyph-kai-5bf9","script":"kai","character":"对","reading":"duì","description":"唐且对曰臣未尝闻也。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-对"},{"id":"glyph-kai-5bfa","script":"kai","character":"寺","reading":"sì","description":"sì：(1)古代官署名太常～（古代掌管宗庙礼仪的官署）¤胪～（略同于现代的礼宾司）。\n(2)佛教出家人居住的地方佛～。～观（guàn）。\n(3)伊斯兰教徒礼拜、讲经的地方清真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寺"},{"id":"glyph-kai-5bfb","script":"kai","character":"寻","reading":"xún","description":"精巧,寻仞皆以两臂度之,故仞亦或言八尺,\n⒈找，探求～找。～觅。～访。～求。～根究底。\n⒉随即，不久～即。\n⒊〈古〉长度单位。八尺为～，十六尺为常◇来用\"寻常\"〈表〉平常、普通的意思。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寻"},{"id":"glyph-kai-5bfc","script":"kai","character":"导","reading":"dǎo","description":"教导","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-导"},{"id":"glyph-kai-5bff","script":"kai","character":"寿","reading":"shòu","description":"斯役之价值,直可惊天地,泣鬼神,与武\n⒈生命的年限，又指岁数大～命。高～。～比南山。\n⒉生日～辰。祝～。\n⒊装殓死人的～衣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-寿"},{"id":"glyph-kai-5c01","script":"kai","character":"封","reading":"fēng","description":"fēng：(1)密闭，使跟外面隔绝～闭。密～。～口。～存。～条。～贮。～面。～底。～锁。～顶。冰～雪飘。～山育林。\n(2)用来装信、钱等物的纸套信～。赏～。\n(3)帝王把土地或爵位给予亲属或臣僚～侯。～君（领有封地的贵族）。～邑。～拜（拜官授爵）。～典。～建。\n(4)疆界～疆。～域。～界。\n(5)限制故步自～。\n(6)帝王筑坛祭天～禅（祭天为封”，祭地为禅”）。\n(7)量词，用于装封套的东西一～信。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-封"},{"id":"glyph-kai-5c04","script":"kai","character":"射","reading":"shè；yè；yì","description":"shè：(1)放箭～箭◇羿～日。\n(2)用推力或弹力送出子弹等～击。扫～。发～。～程。～手。\n(3)气体或液体等受到压力迅速流出喷～。注～。\n(4)放出光、热、电波等～电。辐～。～线。照～。反～。\n(5)有所指暗～。影～。\nyè：〔～干〕古书上的一种草，根可入药。\n〔仆～〕中国秦至宋代的官名，宋代以后废。\nyì：〔无～〕a.中国古代音乐十二律之一；b.中国春秋时景王所铸钟名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-射"},{"id":"glyph-kai-5c06","script":"kai","character":"将","reading":"jiāng","description":"扶持,扶助\n奉行,秉承\n⒈快要～要。她～去北京。\n⒉介词。把～祖国建设得更加美好。\n⒊拿，用，随顺～功补过。～计就计。\n⒋调养，保养～养。～息。\n⒌扶，持，带领出入相扶～。挈妇～雏。\n①对高级军官的称呼。\n⒍用语言刺激你把他～急了。\n⒎〈方〉兽类生子～驹子。～小猪儿。\n⒏副词。又，且～信～疑。\n⒐连词⊥，与，同暂伴月～影。\n⒑助词。用于动词\"出来\"、\"起来\"、\"进去\"等的中间跳～出来～起来。打～进去。迎～上去。\n⒈带兵的人，高级武官～领。猛～。虎～。\n⒉敢想敢干的人闯～。\n⒊军衔名。在校级之上少～。上～。\n⒋统率，指挥～兵打仗。\n将qiāng 1.愿;请。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-将"},{"id":"glyph-kai-5c09","script":"kai","character":"尉","reading":"wèi；yù","description":"wèi：(1)古代官名，一般是武官县～。都～。卫～。太～。\n(2)军衔的一级，在校以下～官。少～。上～。\n(3)姓。\n〔～氏〕地名，在中国河南省。\nyù：〔～迟〕复姓。\n〔～犁〕地名，在中国新疆维吾尔自治区。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尉"},{"id":"glyph-kai-5c0a","script":"kai","character":"尊","reading":"zūn","description":"zūn：(1)地位或辈分高～长（zhǎng）。～卑。～贵。～严。\n(2)敬重～敬。自～。～重。\n(3)敬辞，称与对方有关的人或事物～府。令～。～姓。～驾。\n(4)量词一～佛像。\n(5)古同撙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尊"},{"id":"glyph-kai-5c0f","script":"kai","character":"小","reading":"xiǎo","description":"xiǎo：(1)指面积、体积、容量、数量、强度、力量不及一般或不及所比较的对象，与大”相对～雨。矮～。短～精悍。\n(2)范围窄，程度浅，性质不重要～事。～节。～题大作。～打～闹。\n(3)时间短～坐。～住。\n(4)年幼小，排行最末～孩。\n(5)谦辞～弟。～可。～人（a.谦称自己，指地位低；b.指人格卑鄙的人；c.指子女；d.小孩儿）。\n(6)妾～房。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-小"},{"id":"glyph-kai-5c11","script":"kai","character":"少","reading":"shǎo；shào","description":"shǎo：(1)数量小的，与多”相对多～。～量。～许。\n(2)缺，不够缺～。减～。\n(3)不经常～有。～见。\n(4)短时间～等。～候。～顷。\n(5)丢，遗失屋里～了东西。\n(6)轻视且夫我尝闻～仲尼之闻而轻伯夷之义者，如吾弗信，今我睹子之难穷也”。\n长；老；多；\nshào：(1)年纪轻或年轻人～年。～女。～壮（年轻力壮）。\n(2)古代辅佐长官的副职～傅。～保。\n(3)次级的～校。～将（jiàng）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-少"},{"id":"glyph-kai-5c14","script":"kai","character":"尔","reading":"ěr","description":"后引作薾。华盛的样子\n近。通迩”\n浅近\n⑥词尾。相当于'地'、'然'卓～、率～。\n【尔曹】你们这些人。\n【尔虞我诈】互相猜疑，互相欺骗。又作尔诈我虞。\n【尔诈我虞】见【尔虞我诈】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尔"},{"id":"glyph-kai-5c16","script":"kai","character":"尖","reading":"jiān","description":"jiān：(1)锐利的末端或细小的部分～锐。～刻（说话尖酸刻薄）。～酸。打～。～端。\n(2)感觉敏锐眼～。\n(3)声音高而细～脆。～嫩。\n(4)出类拔萃的人或事物技术～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尖"},{"id":"glyph-kai-5c18","script":"kai","character":"尘","reading":"chén","description":"①尘土，附着在器物上或飞扬的细土除～器。\n②人间；现实社会红～。\n【尘肺】见【矽肺】。\n【尘芥】比喻轻微、不足重视的东西。芥小草。\n【尘世】佛教、道教所指的现实社会，与其理想世界相对。\n【尘嚣】人多，熙熙攘攘的样子。\n⒈飞扬的或浮面的灰土～土。\n⒉踪迹，事迹步人后～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尘"},{"id":"glyph-kai-5c1a","script":"kai","character":"尚","reading":"shàng","description":"shàng：(1)还（hái），仍然～小。～未。～不可知。\n(2)尊崇，注重～武。～贤（a.崇尚贤人；b.《墨子》篇名，内容阐述墨子的一种政治主张）。\n(3)社会上共同遵从的风俗、习惯等风～。时～。\n(4)矜夸，自负自～其功。\n(5)古，久远故乐之所由来者～矣，非独为一世之所造也”。\n(6)庶几，差不多～飨（希望死者来享用祭品之意）。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尚"},{"id":"glyph-kai-5c1d","script":"kai","character":"尝","reading":"cháng","description":"尝试\n经历\n①吃一点试试；辨别滋味～鲜。\n②曾经未～、何～。\n【尝新】吃应时的新鲜蔬菜、水果等。\n⒉试，试一试～试。\n⒊曾经何～？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尝"},{"id":"glyph-kai-5c24","script":"kai","character":"尤","reading":"yóu","description":"yóu：(1)特异的，突出的～为（wéi）。～异。无耻之～。\n(2)更加，格外～其。\n(3)过失效～（学着别人做坏事）。\n(4)怨恨，归咎怨天～人。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尤"},{"id":"glyph-kai-5c27","script":"kai","character":"尧","reading":"yáo","description":"中国古代的皇帝陶唐氏之号。生于伊,嗣后耆,故称伊耆氏;初封陶,后徙唐,又称伊唐氏”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尧"},{"id":"glyph-kai-5c2c","script":"kai","character":"尬","reading":"gà","description":"gà：〔尴～〕见尴”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尬"},{"id":"glyph-kai-5c31","script":"kai","character":"就","reading":"jiù","description":"jiù：(1)凑近，靠近避难～易。～着灯看书。\n(2)到，从事，开始进入～位。～业。～寝。～任。～绪。～医。高～。\n(3)依照现有情况或趁着当前的便利，顺便～近。～便。～事论事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-就"},{"id":"glyph-kai-5c34","script":"kai","character":"尴","reading":"gān","description":"处境尴尬\n尴尬的局面\n尴尬人\n神情尴尬\n①处境窘迫，难办这事搞得很～尬。\n②神色不正，不自然神色～尬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尴"},{"id":"glyph-kai-5c38","script":"kai","character":"尸","reading":"shī","description":"shī：(1)死人的身体～体。～骸。僵～。借～还魂。\n(2)古代祭祀时，代表死者受祭的人。\n〔～位〕空占着职位而不做事，如～～素餐，～～误国”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尸"},{"id":"glyph-kai-5c3a","script":"kai","character":"尺","reading":"chǐ；chě","description":"chǐ：(1)中国市制长度单位（亦称市尺”。一尺等于十寸。西汉时一尺等于0.231米，今三尺等于一米）～素（a.一尺长的白绢，借指小画幅；b.书信）。～短寸长。～牍。\n(2)量长度的器具竹～。\n(3)像尺的东西铁～。仿～。戒～。\n(4)形容微少或短小～布。咫～天涯。\nchě：中国古代乐谱的记音符号，相当于简谱的2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尺"},{"id":"glyph-kai-5c3c","script":"kai","character":"尼","reading":"ní","description":"ní：(1)梵语比丘尼”的简称，佛教中出家修行的女子～姑。～庵。削发为～。\n(2)古同昵”，相近，亲近。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尼"},{"id":"glyph-kai-5c3d","script":"kai","character":"尽","reading":"jìn","description":"尽量,尽可能\n意思同最”,用在方位词的前面\n老是;总\n尽 〈动〉\n表示以某个范围为界限,不得超过\n让先\n任凭,纵使\n惟有落红不禁,尽教飞舞出宫墙。╠\n⒈力所能及的限度～力。～量。\n⒉放在最先住房先～着分给教师。\n⒊任凭～你挑选。\n⒋极，最～前头。～下面。～先考虑。\n⒌老是，只管这几天～是晴天。\n①纵然，即使～管如此。\n②只管，不必考虑的你～管放心。\n⒈完无穷无～。取之不～。\n⒉全部用出，竭力做到～心竭力。～力而为。～职～责。～情欢唱。各～所能。\n⒊达到顶点已到～头。～善～美。\n⒋都，全部～人皆知。满城～带黄金甲。\n⒍见jǐn。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尽"},{"id":"glyph-kai-5c3e","script":"kai","character":"尾","reading":"wěi；yǐ","description":"wěi：(1)鸟兽虫鱼等身体末端突出的部分～巴。～鳍。鸟～。\n(2)末端排～。船～。～声。～骨。～灯。～数。～音。结～。扫～。虎头蛇～。\n(3)在后面跟～随。～追。\n(4)量词，指鱼三～鱼。\n(5)星名，二十八宿之一。\n头；首；\nyǐ：(1)特指马尾（wěi）巴上的毛马～罗。马～儿提豆腐╠提溜不起来。\n(2)特指蟋蟀等尾部的针状物三～儿（雌蟋蟀）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尾"},{"id":"glyph-kai-5c3f","script":"kai","character":"尿","reading":"niào；suī","description":"niào：(1)小便，肾脏的排泄液～液。～布。～肥。～素。\n(2)排泄小便～尿。\nsuī：小便（限于名词）尿（niào）～。～脬（膀胱。亦作尿泡”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-尿"},{"id":"glyph-kai-5c40","script":"kai","character":"局","reading":"jú；jv","description":"jú：(1)部分～部。～麻（局部麻醉）。\n(2)机关及团体组织分工办事的单位教育～。\n(3)某些商店的名称书～。\n(4)棋盘棋～。\n(5)下棋或其他比赛进行一次下了一～棋。\n(6)着棋的形势，喻事情的形势、情况时～。大～。～面。～势。\n(7)弯曲。\n(8)骗人的圈套骗～。\n(9)畏缩不安，狭隘，不舒展～促。～限。\n(10)人的器量～量（liàng）。器～。～度（dù）。\n(11)某些聚会饭～。饮～。赌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-局"},{"id":"glyph-kai-5c41","script":"kai","character":"屁","reading":"pì","description":"pì：(1)从肛门排出的臭气～滚尿流。\n(2)小，没有作用顶个～。\n(3)胡说，没有道理的话这简直是～话。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屁"},{"id":"glyph-kai-5c42","script":"kai","character":"层","reading":"céng","description":"构成整个事物的一个层次\n重叠\n层台累榭。\n①量词。用于重叠、可分出层次的事物千～饼、三～楼。\n②重叠；重复～峦叠嶂。\n【层出不穷】接连不断地出现，没有尽头。层重迭；重复。穷尽；完。\n【层递】〈语〉修辞学上辞格之一。用结构相似的语句表达层层递进的事理。如'火车风驰电掣地猛冲过来……五十米，马不动。四十米，马不动。三十米，马还是不动！'\n【层析】色层分析的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-层"},{"id":"glyph-kai-5c45","script":"kai","character":"居","reading":"jū；jv","description":"jū：(1)住～住。～民。同～。隐～。～处（chǔ）（a.住所；b.指生活处境）。～处（chù）（住所）。\n(2)居住的地方新～。故～。迁～。蜗～（喻窄小的住所）。\n(3)当，占，处于～首。～中。～高临下。二者必～其一。\n(4)安着，怀着～心（怀着某种念头，有贬义）。\n(5)积蓄，储存奇货可～（a.指商人把珍稀的货物储存起来，等待时机高价出售；b.喻挟持某种技艺或某种事物以谋求功名利禄）。\n(6)停留～守。\n(7)平时平～。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-居"},{"id":"glyph-kai-5c48","script":"kai","character":"屈","reading":"qū","description":"qū：(1)使弯曲，与伸”相对～曲（qū）。～折。～膝。～伸（弯曲和伸直，引申为失意和得意）。首～一指。卑躬～膝。\n(2)低头，降服～服。～从。威武不～。\n(3)冤枉，叫人不痛快冤～。委～。～辱。～才。～就（受委屈而担任某种职务，常用于请人任职的客套话）。～驾。～己待人。\n(4)理亏～心（亏心，昧心）。理～词穷。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屈"},{"id":"glyph-kai-5c49","script":"kai","character":"屉","reading":"tì","description":"tì：(1)器物中可以拿出的盛放物体的部分，常常是匣形或是分层的格架抽～。笼～。\n(2)某些床或椅子的架子上可以取下的部分床～。棕～。藤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屉"},{"id":"glyph-kai-5c4a","script":"kai","character":"届","reading":"jiè","description":"jiè：(1)到～时。～期。\n(2)量词，略同于次”，用于定期的会议或毕业的班级等上～。应～（指本期的，用于毕业生）。第一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-届"},{"id":"glyph-kai-5c4b","script":"kai","character":"屋","reading":"wū","description":"wū：(1)房，房间～子。～宇。房～。\n(2)家吴中过客莫思家，江南画船如～里。”\n(3)车盖，覆盖物黄～（古代帝王所乘车上以黄缯为里的车盖，亦指帝王车）。～社（王朝倾覆的代称）。\n(4)古代井田的区划，一屋合三百亩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屋"},{"id":"glyph-kai-5c4e","script":"kai","character":"屎","reading":"shǐ","description":"人或动物排出的粪便。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-5c4f","script":"kai","character":"屏","reading":"píng；bǐng","description":"píng：(1)遮挡～风。～障。～蔽。～藩（屏风”和藩篱”，喻卫国的重臣）。～翰（喻卫国的重臣）。\n(2)字画的条幅，通常以四幅或八幅为一组画～。四扇～。\nbǐng：(1)除去，排除～除。～弃。～斥。～退。\n(2)抑止（呼吸）～气。～息。～声。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屏"},{"id":"glyph-kai-5c51","script":"kai","character":"屑","reading":"xiè","description":"xiè：(1)碎末～子。纸～。\n(2)琐碎～～。琐～（细微小的事情）。\n(3)认为值得（做）不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屑"},{"id":"glyph-kai-5c55","script":"kai","character":"展","reading":"zhǎn","description":"zhǎn：(1)张开，舒张开～开。～示。～玩。～现。～宽。～望。发～。愁眉不～。\n(2)延缓，放宽期限～延。～期。～缓。\n(3)察看，省（xǐng）视～墓。\n(4)陈列～品。～销。～播。～评。\n(5)施行，发挥（能力）～拜。开～。施～。一～宏图。\n(6)古同辗”，辗转。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-展"},{"id":"glyph-kai-5c5e","script":"kai","character":"属","reading":"shǔ","description":"种类。亦特指牲类\n亲属\n侪辈。指同一类人\n若属皆且为所\n⒈类，同一类型的种～。金～。非金～。\n⒉同一家族的亲～。家～。\n⒊有管辖关系的直～。隶～。归～。附～。\n⒋是事～可行。经查～实。\n⒌归类～于医学。\n⒍为谁所有那支笔～你的。\n⒈连接，跟着前后相～。\n⒉编写，连缀～文。～辞。\n⒊专注～意。～望。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-属"},{"id":"glyph-kai-5c60","script":"kai","character":"屠","reading":"tú","description":"tú：(1)宰杀牲畜，引申为大量残杀～宰。～刀。～户。～夫。～杀。～戮。～城。～龙之技（喻高超而不实用的技艺）。\n(2)姓。\n〔～苏〕a.古书上说的一种草；b.草庵；c.古代一种酒名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屠"},{"id":"glyph-kai-5c61","script":"kai","character":"屡","reading":"lǚ","description":"屡（屢）lǚ多次～次。～见不鲜。～战～胜。～禁不止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屡"},{"id":"glyph-kai-5c65","script":"kai","character":"履","reading":"lǚ；lv","description":"lǚ：(1)鞋西装革～。削足适～。\n(2)践踩，走过～历（a.个人的经历；b.记载履历的文件）。～任。～险如夷（走在险峻的地方，像走在平坦的路上，喻身处险境而不畏惧，又喻安全地度过险境）。如～薄冰（身临其境）。\n(3)步伐步～维艰。\n(4)执行，实行～行。～约。\n(5)指领土赐我先君～”。\n〔～带〕在拖拉机、坦克车等的车轮上围绕的钢质链带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-履"},{"id":"glyph-kai-5c6f","script":"kai","character":"屯","reading":"tún；zhūn","description":"tún：(1)聚集，储存～粮。～积。～聚。\n(2)驻军防守～兵。～垦。～田（驻军开垦田地）。\n(3)村庄皇姑～。～子（村庄）。\nzhūn：困难～蹇（不顺利，艰难困苦）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屯"},{"id":"glyph-kai-5c71","script":"kai","character":"山","reading":"shān","description":"地面上高耸的地形，也用来指山峦。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-5c79","script":"kai","character":"屹","reading":"yì","description":"yì：山势高耸，喻坚定不可动摇～～（高耸的样子）。～立。～然不动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屹"},{"id":"glyph-kai-5c7f","script":"kai","character":"屿","reading":"yǔ","description":"平地小山","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-屿"},{"id":"glyph-kai-5c81","script":"kai","character":"岁","reading":"suì","description":"年的别称\n⒈年，时间，光阴～首。～末。～月如流。\n⒉计算年龄的单位～数。六～入学。\n⒊庄稼的收成～景。善～。丰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岁"},{"id":"glyph-kai-5c82","script":"kai","character":"岂","reading":"qǐ","description":"同恺”。安乐\n岂”假借作虚词,用在句中或句首,表示反问。\n相当于难道”,怎么”\n相当\n⒉〈古〉通\"恺\"、\"凯\"。柔和，快乐。\n岂kǎi 1.和乐。参见\"岂乐\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岂"},{"id":"glyph-kai-5c94","script":"kai","character":"岔","reading":"chà","description":"chà：(1)山脉分歧的地方，亦指道路、河流分歧的地方～道。～子。大沟小～。\n(2)转移话题，未按原来的方向行进而偏到一边打～。走～了。\n(3)互相让开或调换把这两个会的时间～开。\n(4)方言，嗓音失常～调（diào）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岔"},{"id":"glyph-kai-5c96","script":"kai","character":"岖","reading":"qū","description":"道路险阻不平\n形容山势峻险","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岖"},{"id":"glyph-kai-5c97","script":"kai","character":"岗","reading":"gǎng","description":"同岡”。山脊,山岭\n同 本 义\n土石坡儿\n⒈守卫的位置站～。～哨。门～。\n⒉高起的土坡土～子。黄泥～儿。\n⒊平面上突起的长道肉～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岗"},{"id":"glyph-kai-5c9b","script":"kai","character":"岛","reading":"dǎo","description":"字省作岛”\n岛 dǎo海洋里被水环绕、面积比大陆小的陆地。也指江河湖里被水环绕的陆地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岛"},{"id":"glyph-kai-5ca9","script":"kai","character":"岩","reading":"yán","description":"yán：(1)高峻的山崖～壁。～壑。\n(2)构成地壳的石头～石。～洞。～浆。～层。熔～。\n(3)险要，险峻～险。～邑。\n(4)山洞中空成～。～居穴处。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岩"},{"id":"glyph-kai-5cad","script":"kai","character":"岭","reading":"lǐng；líng","description":"líng：〔～嵤〕山深貌。亦作岭巆”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岭"},{"id":"glyph-kai-5cb3","script":"kai","character":"岳","reading":"yuè","description":"yuè：(1)高大的山五～（中国五大名山，即东岳泰山，西岳华山，南岳衡山，北岳恒山，中岳嵩山）。\n(2)称妻的父母或妻的叔伯～丈。～父。～母。叔～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岳"},{"id":"glyph-kai-5cb8","script":"kai","character":"岸","reading":"àn","description":"àn：(1)水边的陆地河～。上～。两～。\n(2)高大伟～（魁伟，高直）。魁～。\n(3)高傲～忽（傲慢）。傲～。\n(4)头饰高戴，前额外露～帻（把头巾掀起露出前额，表示态度洒脱，不拘束）。\n(5)古同犴”，乡间牢狱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-岸"},{"id":"glyph-kai-5ce1","script":"kai","character":"峡","reading":"xiá","description":"从峡度栈以上。\n形容词。狭窄\n⒈两面有山夹着的水道长江三～。\n⒉两山之间或两陆地之间的狭窄地带～谷。地～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峡"},{"id":"glyph-kai-5ce6","script":"kai","character":"峦","reading":"luán","description":"泛指山\n⒈小而尖的山孤～。丘～崩摧。\n⒉山脊，山梁，泛指山，多指连着的山冈～。峰～起伏。重～迭嶂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峦"},{"id":"glyph-kai-5ce8","script":"kai","character":"峨","reading":"é","description":"é：高～～。～冠博带。巍～。嵯～。\n〔～嵋〕山名，在中国四川省。亦作蛾眉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峨"},{"id":"glyph-kai-5ced","script":"kai","character":"峭","reading":"qiào","description":"qiào：(1)山又高又陡陡～。～壁。峻～。～立。～丽（a.陡峭而多姿；b.文辞遒劲华美）。～拔。\n(2)形容严峻～寒。～急。～劲。～厉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峭"},{"id":"glyph-kai-5cf0","script":"kai","character":"峰","reading":"fēng","description":"fēng：(1)高而尖的山头山～。～巅。～峦。高～。险～。\n(2)形状像山峰的东西驼～。浪～。\n(3)最高处登～造极。～年（自然界中某种活动达到高峰的年度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峰"},{"id":"glyph-kai-5cfb","script":"kai","character":"峻","reading":"jùn","description":"jùn：(1)山高而陡高～。险～。～峭。～拔。\n(2)高大～德。～节。\n(3)严厉苛刻～刻。～厉。严～。严刑～法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-峻"},{"id":"glyph-kai-5d07","script":"kai","character":"崇","reading":"chóng","description":"chóng：(1)高～山峻岭。～高。～论闳议（指高出一般人的讨论。亦作崇论宏议”）。\n(2)尊重，推重～敬。～拜。～尚。推～。尊～。\n(3)古同终”，终了。\n(4)充，充满～酒于觞。\n(5)增长今将～诸侯之奸”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崇"},{"id":"glyph-kai-5d0e","script":"kai","character":"崎","reading":"qí","description":"qí：〔～岖〕形容山路不平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崎"},{"id":"glyph-kai-5d14","script":"kai","character":"崔","reading":"cuī","description":"cuī：姓。\n〔～巍〕山、建筑物高大伟岸。\n〔～嵬〕a.有石头的土山；b.高大。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崔"},{"id":"glyph-kai-5d16","script":"kai","character":"崖","reading":"yá","description":"yá：(1)高地的边，陡立的山边山～。悬～。～谷。～壑。～壁。～葬（悬棺葬）。～岸。悬～勒马。\n(2)边际～略（大略，梗概）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崖"},{"id":"glyph-kai-5d1b","script":"kai","character":"崛","reading":"jué","description":"jué：高起，突起～起（a.山峰突起，如泰山平地～～”；b.喻兴起，如义军～～于村野”）。～立（耸立）。～崎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崛"},{"id":"glyph-kai-5d29","script":"kai","character":"崩","reading":"bēng","description":"bēng：(1)倒塌～塌。～坍。～毁。～解（jiě）。～溃。～决。～颓。分～离析。\n(2)破裂～裂。把气球吹～了。\n(3)崩裂的东西击中放爆竹～了手。\n(4)败坏礼坏乐（yuè）～。\n(5)称枪毙拉出去～了。\n(6)君主时代称帝王死驾～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崩"},{"id":"glyph-kai-5d2d","script":"kai","character":"崭","reading":"zhǎn","description":"程度副词≤,特别\n崭zhǎn高峻，突出～岩。～新。～露头角。\n崭chán 1.见\"崭２岩\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-崭"},{"id":"glyph-kai-5d4c","script":"kai","character":"嵌","reading":"qiàn；kàn","description":"qiàn：把东西填镶在空隙里～入。镶～。\nkàn：〔赤～〕地名，在中国台湾省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嵌"},{"id":"glyph-kai-5dc5","script":"kai","character":"巅","reading":"diān","description":"顶部\n头部\n巅峰\n巅 diān山顶。又作'颠'。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巅"},{"id":"glyph-kai-5dcd","script":"kai","character":"巍","reading":"wēi","description":"wēi：高大～峨。～焕（高大壮观）。～然。～～。崔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巍"},{"id":"glyph-kai-5ddd","script":"kai","character":"川","reading":"chuān","description":"chuān：(1)河流名山大～。～流不息。\n(2)平原，平地平～。米粮～。\n(3)特指中国四川省～剧。～菜。～贝。\n〔～资〕旅费。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-川"},{"id":"glyph-kai-5dde","script":"kai","character":"州","reading":"zhōu","description":"zhōu：(1)古代的一种行政区划，所辖地区的大小历代不同（后多用于地名）～县〖～。\n(2)中国一种民族自治行政区划海南省黎族苗族自治～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-州"},{"id":"glyph-kai-5de1","script":"kai","character":"巡","reading":"xún","description":"xún：(1)到各处去，来回走动查看～弋（指舰艇在海上巡逻）。～游。～天（指在天空巡游）。～回。～抚。～视。～幸（古代特指帝王出巡到达某地）。～逻。\n(2)酒席上给全座依次斟酒一遍～杯（主人在宴席上依次向客人劝酒）。酒过三～，菜过五味。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巡"},{"id":"glyph-kai-5de2","script":"kai","character":"巢","reading":"cháo","description":"cháo：(1)鸟搭的窝，亦指蜂、蚁等动物的窝；借指敌人或盗贼的藏身之所鸟～。蜂～。～窟。匪～。～穴。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巢"},{"id":"glyph-kai-5de5","script":"kai","character":"工","reading":"gōng","description":"gōng：(1)个人不占有生产资料，依靠工资收入为生的劳动者～人。～人阶级。～农联盟。\n(2)制造生产资料和生活资料的生产事业～业。～业革命。\n(3)从事体力或脑力劳动～作。～厂。竣～。\n(4)工作量记～。这个工程需要三十个～。\n(5)技术和技术修养唱～儿。～夫（ａ．本领，造诣，亦作功夫”；ｂ．时间）。～力。\n(6)细致，精巧～巧。～整。～笔（中国画技法，用笔工整，注重细部的描绘）。\n(7)善于，长于～书善画。～于心计。\n〔～尺（chě）〕中国古代一种记谱符号体系，有十个字合、四、一、上、尺、工、凡、六、五、乙，相当于简谱的５６７1234567。工”相当于3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-工"},{"id":"glyph-kai-5de6","script":"kai","character":"左","reading":"zuǒ","description":"zuǒ：(1)面向南时，东的一边，与右”相对～手。～方。～右。～膀右臂。\n(2)地理上指东方山～。江～。\n(3)指政治思想上进步或超过现实条件许可的过头思想和行动～派。～翼。～倾。\n(4)斜，偏，差错～脾气。～嗓子。\n(5)降低官职～迁。\n(6)古同佐”，佐证。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-左"},{"id":"glyph-kai-5de7","script":"kai","character":"巧","reading":"qiǎo","description":"qiǎo：(1)技能好，灵敏～妙。～思。～劲。～干（gàn）。精～。轻～。乖～。心灵手～。～发奇中。\n(2)美好～笑（指美好的笑貌）。\n(3)虚伪（特指语言）～言。～诈。～辩。～言令色。\n(4)恰好～合。～遇。恰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巧"},{"id":"glyph-kai-5de8","script":"kai","character":"巨","reading":"jù；jv","description":"jù：(1)大，很大～大。～人（ａ．身材异常高的人；ｂ．童话里指比一般人高大，有神力的人；ｃ．喻有巨大影响和贡献的人）。～匠（泛称在科学或文艺上有极大成就的人）。～子（ａ．中国战国时墨家学派领袖的尊称；ｂ．在某方面卓有成就，有声望的人）。艰～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巨"},{"id":"glyph-kai-5de9","script":"kai","character":"巩","reading":"gǒng","description":"使坚固\n恐惧\n中国河南省县名","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巩"},{"id":"glyph-kai-5deb","script":"kai","character":"巫","reading":"wū","description":"wū：(1)以祈祷求神骗取财物的人～婆。女～。男～。～术。小～见大～（喻小的跟大的一比，就显得小不如大）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巫"},{"id":"glyph-kai-5dee","script":"kai","character":"差","reading":"chà；chā；chāi；cī","description":"chà：(1)错误话说～了。\n(2)不相当，不相合～不多。\n(3)缺欠还～十元钱。\n(4)不好，不够标准～等。成绩～。\n好；\nchā：(1)不同，不同之点～别。～距。～额。～价。\n(2)大致还可以～可。\n(3)错误～错。偏～。～池。\n(4)数学上指减法运算中的得数～数。四减二的～是二。\n好；\nchāi：(1)派遣去做事～遣。\n(2)旧时称被派遣的人～人。解～。\n(3)被派遣去做的事～事。公～。出～。\n好；\ncī：〔参（cēn）～〕见参3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-差"},{"id":"glyph-kai-5df1","script":"kai","character":"己","reading":"jǐ","description":"jǐ：(1)对别人称本身自～。知～。反求诸～。推～及人。～所不欲，勿施于人。\n(2)天干的第六位，用作顺序第六的代称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-己"},{"id":"glyph-kai-5df2","script":"kai","character":"已","reading":"yǐ","description":"yǐ：(1)止，罢了学不可以～。死而后～。\n(2)表示过去～经。事～至此。～往。业～。\n(3)后来，过了一些时间，不多时～忽不见。\n(4)太，过不为～甚。\n(5)古同以”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-已"},{"id":"glyph-kai-5df3","script":"kai","character":"巳","reading":"sì","description":"sì：(1)地支的第六位，属蛇。\n(2)用于计时～时（上午九点至十一点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巳"},{"id":"glyph-kai-5df4","script":"kai","character":"巴","reading":"bā","description":"bā：(1)粘结着的东西泥～。锅～。\n(2)粘贴，依附在别的东西上饭～锅了。～结别人。\n(3)贴近前不～村，后不～店。\n(4)盼，期望～望。\n(5)张开～着眼睛。\n(6)古国名，在今中国四川省东部。\n(7)中国四川省东部，泛指四川～蜀。～山蜀水。\n(8)词尾，读轻声尾～。嘴～。\n(9)大蛇～蛇（传说中能吞大象的蛇）。\n(10)气压的压强单位。\n(11)压强单位。\n(12)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巴"},{"id":"glyph-kai-5df7","script":"kai","character":"巷","reading":"xiàng；hàng","description":"xiàng：胡同，里弄小～。陋～。穷～。～陌（街道）。～战（在城市街巷里进行的战斗）。穷街陋～。\nhàng：义同（一）。\n〔～道〕采矿或探矿时挖的坑道。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巷"},{"id":"glyph-kai-5dfe","script":"kai","character":"巾","reading":"jīn","description":"jīn：擦东西或包裹、覆盖东西的用品，多用纺织品制成手～。围～。领～。枕～。餐～。～帼（帼”是古代妇女的头巾，指妇女，如～～英雄”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巾"},{"id":"glyph-kai-5e01","script":"kai","character":"币","reading":"bì","description":"泛指车马皮帛玉器等礼物\n币 bì货币人民～、金～、硬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-币"},{"id":"glyph-kai-5e02","script":"kai","character":"市","reading":"shì","description":"shì：(1)做买卖或做买卖的地方开～。菜～。～井（街，市场）。～曹。～侩（旧指买卖的中间人、唯利是图的奸商；现泛指贪图私利的人）。\n(2)买～义。～恩（买好，讨好）。\n(3)人口密集的行政中心或工商业、文化发达的地方城～。都（dū）～。～镇。\n(4)一种行政区划，有中央直辖和省（自治区）辖等北京～。南京～。\n(5)中国人民习惯使用的度量衡单位～制。～尺。～斤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-市"},{"id":"glyph-kai-5e03","script":"kai","character":"布","reading":"bù","description":"bù：(1)棉、麻及棉型化学短纤维经纺纱后的织成物～匹。～帛。～衣。\n(2)古代的一种钱币。\n(3)宣告，对众陈述宣～。发～。～告。开诚～公（推诚相见，坦白无私）。\n(4)分散到各处散～。遍～。星罗棋～。\n(5)流传，散播～道。～施。\n(6)做出安排～置。～景。～局。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-布"},{"id":"glyph-kai-5e05","script":"kai","character":"帅","reading":"shuài","description":"军队中的主将、统帅\n⒈军队中最高级的指挥者元～。统～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帅"},{"id":"glyph-kai-5e06","script":"kai","character":"帆","reading":"fān","description":"fān：利用风力使船前进的布篷～船。～樯。～板。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帆"},{"id":"glyph-kai-5e08","script":"kai","character":"师","reading":"shī","description":"师今为隶属于军的单位,下辖若干旅或团\n泛指军队\n蹇叔之子与师,哭而送之曰晋人御师必于殽。”\n⒈指老师，导师教～。能者为～。～者，所以传道授业解惑也。〈引〉榜样～表。前事不忘，后事之～。\n⒉由师徒关系而产生的～叔。～弟。\n⒊效法，学习～其所长。\n⒋指擅长某种技术的人，又指技术职称医～。厨～。理发～。讲～。会计～。工程～。\n⒌军队出～。雄～百万。\n⒍军队的编制单位。一般是军的下一级，团的上一级。\n①学习的榜样。\n②培养师资的～范大学。\n⒑〈古〉称乐官乐～。\n①传授技艺的老师。\n②称呼有实践经验的工人老～傅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-师"},{"id":"glyph-kai-5e0c","script":"kai","character":"希","reading":"xī","description":"xī：(1)少～少（shǎo）。～罕。～奇。～有。～世。\n(2)盼望～望。～冀。～图（心里盘算达到某种目的）。～求（ａ．希望得到；ｂ．希望和要求）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-希"},{"id":"glyph-kai-5e10","script":"kai","character":"帐","reading":"zhàng","description":"⒈用布、纱、尼龙等做成的帷幕～幕。篷～。蚊～子。特指军用帷幕营～。攻入～中。\n⒉钱财出入的记载记～。现金日记～。\n⒊登记账目、户籍的本子或单子～簿。一本～。户籍～。一篇～单。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帐"},{"id":"glyph-kai-5e15","script":"kai","character":"帕","reading":"pà","description":"pà：包头或擦手、脸用的布或绸，多为方形首～。手～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帕"},{"id":"glyph-kai-5e16","script":"kai","character":"帖","reading":"tiē；tiè；tiě","description":"tiè：学习写字时摹仿的样本碑～。字～。画～。\ntiě：(1)便条字～儿。\n(2)邀请客人的纸片～子。请～。\n(3)写着生辰八字的纸片庚～。换～。\n(4)量词，用于配合起来的若干味汤药一～中药。\ntiē：(1)妥适妥～。安～。\n(2)顺从，驯服服～。俯首～耳。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帖"},{"id":"glyph-kai-5e18","script":"kai","character":"帘","reading":"lián","description":"旧时酒家、茶馆作店招的旗帜,用布做成\n帘子,遮蔽门窗的用具\n同奁”\n⒈用布、塑料、竹片、或苇子等做成遮蔽门窗的东西门～。窗～。\n⒉旧时商店门口做标志的旗帜茶～。酒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帘"},{"id":"glyph-kai-5e1a","script":"kai","character":"帚","reading":"zhǒu","description":"zhǒu：扫除尘土、垃圾的用具扫～。笤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帚"},{"id":"glyph-kai-5e1c","script":"kai","character":"帜","reading":"zhì","description":"急挥帜。\n标记","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帜"},{"id":"glyph-kai-5e1d","script":"kai","character":"帝","reading":"dì","description":"dì：(1)宗教徒或神话中称宇宙的创造者和主宰者上～。玉皇大～。\n(2)君主～王。皇～。称～。～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帝"},{"id":"glyph-kai-5e26","script":"kai","character":"带","reading":"dài","description":"①带子或带状物鞋～、车～。\n②区域沿海一～。\n③携带～上一本书。\n④引导～路。\n⑤附带连说～笑。\n⑥含面～微笑。\n【带操】一种以带为器械的艺术体操项目。带子一般为绸缎，长度7米。基本动作有摆动、绕环、蛇形、螺形、抛接等。\n【带分数】〈数〉整数后面带着分数的数。\n【带余除法】〈数〉若a是任一整数，b是任一正整数，则必唯一存在整数q和r，使a=bq+r，其中0≤r≤b。这里，q叫做b除a的不完全商，简称商，r叫做余数。计算不完全商和\n余数的过程叫做带余除法。这个结论可推广到多项式上去。\n【带状纹样】见【二方连续纹样】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-带"},{"id":"glyph-kai-5e2d","script":"kai","character":"席","reading":"xí","description":"xí：(1)用草或苇子编成的成片的东西，古人用以坐、卧，现通常用来铺床或炕等～子。草～。苇～。竹～。凉～。～地而坐。～卷（juǎn）。\n(2)座位～位。～次。出～。列～。\n(3)酒筵，成桌的饭菜筵～。宴～。酒～。\n(4)特指议会中当选的人数四～。\n(5)职位主～。西～（塾师）。\n(6)量词一～酒。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-席"},{"id":"glyph-kai-5e2e","script":"kai","character":"帮","reading":"bāng","description":"泛指物体两侧或周围的部分\n伙,群\n白菜等蔬菜的外部厚硬叶\n帮助\n①帮助。\n②从事雇佣劳动～工。\n③物体两旁或周围的部分鞋～。\n④某些蔬菜外层的叶子老白菜～子。\n⑤群；伙；集团匪～。\n⑥量词一大～老同学。\n⑦帮会青～。\n【帮腔】\n①戏曲音乐中'一唱众合'与'后台齐唱'的帮和唱腔形式。其作用不仅是陪衬或代替管弦乐伴奏，而主要是描写环境，加强舞台气氛。又称托腔或接声。\n②比喻帮助、支持别人，替别人说话你不要给他～了。\n【帮闲】\n①文人受他人豢养，给他人装点门面，为他人效劳。\n②帮闲的文人。\n【帮凶】\n①帮助行凶作恶。\n②帮助行凶作恶的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帮"},{"id":"glyph-kai-5e37","script":"kai","character":"帷","reading":"wéi","description":"wéi：围在四周的帐幕～幕。～幔。～幄（军用的帐幕）。～子。～帐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帷"},{"id":"glyph-kai-5e38","script":"kai","character":"常","reading":"cháng","description":"cháng：(1)长久，经久不变～数。～量（亦称恒量”）。～项。～任。～年。～驻。～住。～备不懈。\n(2)时时，不只一次～～。～客。时～。经～。\n(3)普通的，一般的～识。～务。～规。～情。～人。平～。反～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-常"},{"id":"glyph-kai-5e3d","script":"kai","character":"帽","reading":"mào","description":"mào：(1)盖头的东西～子。草～。凉～。军～。礼～。\n(2)器物的顶罩或套儿笔～儿。螺丝～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帽"},{"id":"glyph-kai-5e45","script":"kai","character":"幅","reading":"fú","description":"fú：(1)布的宽度～面。双～。宽～。\n(2)泛指事物的宽度～度。～员（幅”是宽度，员”是周围。指疆域或领土的面积。如我国～～广大”）。振～。篇～。\n(3)边缘边～。\n(4)量词，用于布帛、图画等一～画。五～布。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幅"},{"id":"glyph-kai-5e4c","script":"kai","character":"幌","reading":"huǎng","description":"huǎng：帐幔，帘帷何时倚虚～，双照泪痕干？”\n〔～子〕ａ．商店门外的招牌或标志物；ｂ．喻进行某种活动时所假借的名义。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幌"},{"id":"glyph-kai-5e55","script":"kai","character":"幕","reading":"mù","description":"mù：(1)覆着在上面的帐帐～。夜～。～天席地。\n(2)垂挂在舞台前部的帷帐～布。～后。开～。银～。帷～。\n(3)古代战争期间将帅办公的地方～府。～宾。～僚。\n(4)戏剧较完整的段落，亦喻生活中的情景序～。独～剧。\n(5)古代作战时用的铁制臂甲和腿甲。\n(6)覆盖解朝服而～之”。\n(7)古同漠”，沙漠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幕"},{"id":"glyph-kai-5e62","script":"kai","character":"幢","reading":"zhuàng；chuáng","description":"chuáng：(1)古代原指支撑帐幕、伞盖、旌旗的木竿，后借指帐幕、伞盖、旌旗。\n(2)刻着佛号或经咒的石柱经～。石～。\n〔～～〕形容影子摇晃，如人影～～”。\nzhuàng：量词，指房屋一～大楼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幢"},{"id":"glyph-kai-5e72","script":"kai","character":"干","reading":"gān；gàn","description":"gān：干燥；干预；牵涉；古代盾牌。gàn：做事；事物的主体部分，如干活、树干、骨干。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-5e73","script":"kai","character":"平","reading":"píng","description":"píng：(1)不倾斜，无凹凸，像静止的水面一样～地。～面。～原。\n(2)均等～分。～行（xíng）。抱打不～。公～合理。\n(3)与别的东西高度相同，不相上下～列。～局。～辈。\n(4)安定、安静～安。～服。\n(5)治理，镇压～定。\n(6)抑止（怒气）他把气～了下去。\n(7)和好宋人及楚人～”。\n(8)一般的，普通的～民。～庸。～价。～凡。\n(9)往常，一向～生（ａ．从来；ｂ．终身）。～素。\n(10)汉语四声之一～声。～仄。\n(11)姓。\n(12)古同评”，评议。\n〔～假（jiǎ）名〕日本文所用的草书字母。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-平"},{"id":"glyph-kai-5e74","script":"kai","character":"年","reading":"nián","description":"nián：(1)地球绕太阳一周的时间一～。三～五载。\n(2)每年的～会。～鉴。～利。～薪。\n(3)一年的开始～节。新～。\n(4)有关年节的（用品）～画。～礼。～货。\n(5)时期，时代近～。～华。～号（ａ．帝王用的纪年名称；ｂ．公元纪年名称）。～限。～深日久。\n(6)收成～成。～景。～谨。荒～。\n(7)岁数～纪。～事（岁数）。～高。～轮。\n(8)人一生所经年岁的分期幼～。童～。青～。壮～。中～。老～。\n(9)科举时代同年考中者的互称～兄。～谊（同年登科的关系）。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-年"},{"id":"glyph-kai-5e76","script":"kai","character":"并","reading":"bìng；bīng","description":"bìng：(1)合在一起～拢∠～。兼～。\n(2)一齐，平排着～驾齐驱。～重（zhòng）。～行（xíng）。\n(3)连词，表平列或进一层～且。\n(4)用在否定词前，加强否定的语气，表不像预料的那样～不容易。\nbīng：中国山西省太原市的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-并"},{"id":"glyph-kai-5e78","script":"kai","character":"幸","reading":"xìng","description":"xìng：(1)意外地得到成功或免去灾害～运。侥～。～存。～免。～未成灾。\n(2)福气～福。荣～。\n(3)高兴庆～。欣～。～甚。\n(4)希望～勿推却。～来告语之。\n(5)宠爱宠～。得～。\n(6)指封建帝王到达某地巡～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幸"},{"id":"glyph-kai-5e7b","script":"kai","character":"幻","reading":"huàn","description":"huàn：(1)空虚的，不真实的～想。～影。～境。～灭（受到现实的打击而消灭）。亦真亦～。虚～。梦～。\n(2)变化～化（奇异的变化）。变～莫测。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幻"},{"id":"glyph-kai-5e7c","script":"kai","character":"幼","reading":"yòu","description":"yòu：(1)年纪小，初出生的～儿。～虫。～苗。～年。\n(2)小孩儿～教（jiào）。～师。扶老携～。\n(3)对儿童爱护～吾幼，以及人之幼。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幼"},{"id":"glyph-kai-5e7d","script":"kai","character":"幽","reading":"yōu","description":"yōu：(1)隐藏，不公开的～会。～居（ａ．隐居；ｂ．幽静的住处）。～愤。～咽。\n(2)形容地方很僻静又光线暗～谷。～静。～暗。\n(3)沉静而安闲～闲。～趣（幽雅的趣味）。～婉。\n(4)把人关起来，不让跟外人接触～禁。～闭。～囚。\n(5)迷信的人指阴间～灵。～魂。\n(6)古地名，大致相当于今中国河北省、辽宁省南部一带～州。～燕（yān）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幽"},{"id":"glyph-kai-5e7f","script":"kai","character":"广","reading":"guǎng；ān","description":"ān：同庵”，多用于人名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-广"},{"id":"glyph-kai-5e84","script":"kai","character":"庄","reading":"zhuāng","description":"谨严持重\n⒈严肃，端重～严。～重。亦～亦谐。\n⒉村子，田舍村～。山～。\n⒊封建社会里帝王贵族及地主占有的大片土地皇～。～园。祝家～。\n⒋某些商店的名称茶～。钱～。布～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庄"},{"id":"glyph-kai-5e86","script":"kai","character":"庆","reading":"qìng","description":"蜀遣卫尉陈震庆权践位。╠\n⒈棕～祝。～贺。～丰收。～功大会。\n⒉可棕的事佳～。国～。喜～。\n庆qiāng 1.发语词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庆"},{"id":"glyph-kai-5e87","script":"kai","character":"庇","reading":"bì","description":"bì：遮蔽，掩护～护。～短。包～。～荫（ａ．遮住阳光；ｂ．喻包庇袒护）。～佑（保佑）。～护权。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庇"},{"id":"glyph-kai-5e8a","script":"kai","character":"床","reading":"chuáng","description":"chuáng：(1)供人睡卧的家具～铺。木～。～榻。\n(2)像床的东西车～。机～∮～。\n(3)量词，用于被褥等两～被。\n(4)井上围栏后园凿井银作～，金瓶素绠汲寒浆”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-床"},{"id":"glyph-kai-5e8f","script":"kai","character":"序","reading":"xù","description":"xù：(1)次第顺～。秩～。次～。工～。程～。～数。\n(2)排列次第～次。～列。\n(3)开头的，在正式内容之前的～言。～跋。～曲。～幕。～论。\n(4)古代指送别赠言的文字。\n(5)指季节四～。\n(6)古代地方办的学校庠～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-序"},{"id":"glyph-kai-5e90","script":"kai","character":"庐","reading":"lú","description":"亦泛指简陋居室\n⒈简陋的房屋草～。\n⒉居住可～。\n⒊宾客住的宿舍十里有～，～有饮食。\n⒋庐山，在江西省。\n庐lǘ 1.古邑名。一作\"卢\"。在今湖北襄阳西南。本春秋庐戎国，被楚灭后为楚邑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庐"},{"id":"glyph-kai-5e93","script":"kai","character":"库","reading":"kù","description":"后泛指贮物的屋舍\n⒈贮藏东西的地方或建筑物仓～。书～。大水～。\n⒉电荷量单位\"库伦\"的简称，符号c。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-库"},{"id":"glyph-kai-5e94","script":"kai","character":"应","reading":"yīng；yìng","description":"yīng：应该，应当。yìng：回答，响应，适合，如答应、应对、适应。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-5e95","script":"kai","character":"底","reading":"dǐ；de","description":"dǐ：(1)最下面的部分～层。～座。～下（ａ．下面；ｂ．以后）。～。～肥。\n(2)末了年～。月～。到～。\n(3)根基，基础，留作根据刨根问～。～蕴。～稿。～版。\n(4)图案的基层白～蓝花的瓶子。\n(5)何，什么～事伤感。\n(6)古同抵”，达到。\n顶；\nde：同的3”③。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-底"},{"id":"glyph-kai-5e97","script":"kai","character":"店","reading":"diàn","description":"diàn：(1)售卖货物的铺子～铺。～员。～主。～肆。～堂。商～。书～。\n(2)旅馆客～。旅～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-店"},{"id":"glyph-kai-5e99","script":"kai","character":"庙","reading":"miào","description":"庙在\n⒉〈古〉朝廷、帝王处理政事的地方～堂。廊～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庙"},{"id":"glyph-kai-5e9a","script":"kai","character":"庚","reading":"gēng","description":"gēng：(1)天干的第七位，用作顺序第七的代称。\n(2)年龄同～。年～。生～（人出生的年月）。～帖（tiě）。～齿（年龄）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庚"},{"id":"glyph-kai-5e9c","script":"kai","character":"府","reading":"fǔ","description":"fǔ：(1)储藏文书或财物的地方～库。天～。\n(2)旧时封建贵族和官僚的主宅，泛指一般人的住宅～邸。～第。王～。～上。\n(3)中国唐代至清代的行政区域名，等级在县和省之间开封～。～尹。～治。～试。首～。\n(4)国家行政机关政～。官～。\n(5)古同腑”，脏腑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-府"},{"id":"glyph-kai-5e9e","script":"kai","character":"庞","reading":"páng","description":"脸盘\n多而杂乱的\n高大\n⒈大，高大～大。～然大物。\n⒉多而杂乱～杂。\n⒊脸盘面～。\n庞lóng 1.充实。参见\"庞庞\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庞"},{"id":"glyph-kai-5e9f","script":"kai","character":"废","reading":"fèi","description":"泛指倾圮,倒塌\n废弃;废除\n停止; 中\n⒈停止，放弃～止。～用。～除。作～。～寝忘食。切莫半途而～。〈引〉没有用的，失去功效的～物。～纸。～话连篇。变～为宝。\n⒉荒芜，衰败荒～。～屋。～墟。\n⒊残疾残～。无手足则肢体～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-废"},{"id":"glyph-kai-5ea6","script":"kai","character":"度","reading":"dù；duó","description":"dù：(1)计算长短的器具或单位尺～。刻～。～量衡。\n(2)事物所达到的境界程～。高～。风～。\n(3)分角的单位，一圆周角分为360度角～。\n(4)依照计算的一定标准划分的单位温～。湿～。经～。纬～。浓～。\n(5)电能的单位，一千瓦小时电量的通称。\n(6)法则，应遵行的标准制～。法～。\n(7)哲学上指一定事物保持自己质的数量界限。\n(8)能容受的量气～。\n(9)考虑，打算置之～外。\n(10)过，由此到彼～日。～假。欢～新春。\n(11)量词，次一～。再～。\n(12)僧尼道士劝人出家剃～（剃发出家）。\n(13)姓。\nduó：计算，推测忖～。揣～。审时～势。～德量力。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-度"},{"id":"glyph-kai-5ea7","script":"kai","character":"座","reading":"zuò","description":"zuò：(1)坐位入～。茶～。～谈。宝～。在～。～右铭。\n(2)托着器物的东西。底～儿。\n(3)星空的区域，一群星星～。天琴～。\n(4)量词，多用于较大或固定的物体一～山。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-座"},{"id":"glyph-kai-5ead","script":"kai","character":"庭","reading":"tíng","description":"tíng：(1)堂阶前的院子～院。～园。～除（除”，台阶）。\n(2)厅堂～宇。～闱（父母所属内室，借指父母）。～训（父亲的教诲，亦指家教）。家～。\n(3)审判案件的处所或机构法～。\n(4)古同廷”，朝廷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庭"},{"id":"glyph-kai-5eb5","script":"kai","character":"庵","reading":"ān","description":"ān：(1)圆形草屋（文人的书斋亦多称庵”，如老学～”，影梅～”）。\n(2)小庙（指尼姑居住的）～堂（尼姑庵）。～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庵"},{"id":"glyph-kai-5eb6","script":"kai","character":"庶","reading":"shù","description":"shù：(1)众多～务。～物。～绩。富～。\n(2)平民，百姓～民。～人。黎～。\n(3)宗法制度下家庭的旁支，与嫡”相对～子（妾生的儿子）。～母（嫡出子女称父亲的妾）。～姓（古代称与帝王没有亲属关系的异姓诸侯）。\n(4)表示希望发生或出现某事，进行推测；但愿，或许～竭驽钝，攘除奸凶”。～免于难。～几（ａ．也许可以，表示希望；ｂ．近似，差不多；ｃ．旧指贤者）。～乎可行。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庶"},{"id":"glyph-kai-5eb7","script":"kai","character":"康","reading":"kāng","description":"kāng：(1)安宁～乐（lè）。～平。～宁。\n(2)空，空虚萝卜～了。\n(3)宽阔～庄。～衢（四通八达的大路）。\n(4)无病～健。～复。～泰。健～。\n(5)丰盛小～。～年。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-康"},{"id":"glyph-kai-5eb8","script":"kai","character":"庸","reading":"yōng","description":"yōng：(1)平常，不高明的平～。～医。～言。～俗。～人。昏～。～主（平庸或昏庸的君主）。～夫。～暗（平凡，愚昧）。～～碌碌（没有志气，没有作为）。\n(2)需要无～细述。无～讳言。\n(3)岂，怎么～讵（岂，何以，怎么，亦作庸遽”）。\n(4)中国唐代一种赋税法租～调。\n(5)功劳～绩（功绩）。\n(6)古同佣”，雇佣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庸"},{"id":"glyph-kai-5ec9","script":"kai","character":"廉","reading":"lián","description":"lián：(1)堂屋的侧边～隅（棱角，喻品行端方，有气节）。\n(2)不贪污～洁。～正。～明。\n(3)便（pián）宜，价钱低物美价～。\n(4)察考，访查且～问，有不如吾诏者，以重论之”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廉"},{"id":"glyph-kai-5eca","script":"kai","character":"廊","reading":"láng","description":"láng：(1)房屋前檐伸出的部分，可避风雨，遮太阳～子。前～后厦。\n(2)庑下，殿下外屋～庑（堂前廊屋）。\n(3)有顶的过道长～。走～。画～。游～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廊"},{"id":"glyph-kai-5ed3","script":"kai","character":"廓","reading":"kuò","description":"kuò：(1)空阔，广阔～然。寥～。\n(2)扩大～张。\n(3)空寂孤独悲忧穷戚兮独处～”。\n(4)物体的周围、外缘轮～。耳～。\n(5)古同郭”，外城。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廓"},{"id":"glyph-kai-5ef6","script":"kai","character":"延","reading":"yán","description":"yán：(1)引长～长（cháng）。～续。蔓～。～年益寿。\n(2)展缓，推迟～迟。～缓。～宕。～误。\n(3)引进，请～聘（聘请）。～纳。～师。～医。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-延"},{"id":"glyph-kai-5ef7","script":"kai","character":"廷","reading":"tíng","description":"tíng：封建时代君主受朝问政的地方朝（cháo）～。宫～。～杖。～试（科举时代皇帝的殿试）。～对（ａ．在朝廷中当众对答；ｂ．科举时代皇帝的殿试）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廷"},{"id":"glyph-kai-5efa","script":"kai","character":"建","reading":"jiàn","description":"jiàn：(1)立，设置，成立～立（ａ．开始成立；ｂ．开始产生，开始形成）。～树（建立功业，或所建立的功业）。～国。～都（dū）。～党。～军。～交。～设。～功立业。\n(2)造，筑～造。～筑。修～。新～。兴（xīng）～。筹～。\n(3)提出，倡议～议。～策（出谋献策）。\n(4)指中国福建省～兰。\n(5)北斗的斗柄所指的方位。斗柄农历每月所指的方位不同，因此建”亦转指月份（亦称月建”、月尽”）大～（农历有三十天的月份，亦称大尽”）。小～（农历有二十九天的月份，亦称小尽”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-建"},{"id":"glyph-kai-5f00","script":"kai","character":"开","reading":"kāi","description":"打开,开启\n⒈跟\"关\"相对。把关着的东西打开～门。～窗。～锁。〈引〉\n①放散，张开百花盛～。笑逐颜～。～口讲话。\n②化整体为部分六十四～本。\n门、电键。\n⒉发掘，辟出，使显露出来～发。～辟。～煤矿。～荒山。～采黄金。\n⒊发动，发放，操纵～火车。～枪。～炮。～动机器。\n⒋起始～始。～头。～学。～春。\n⒍举行～会讨论。～学典礼。\n⒎揭示，表明～诚布公。～宗明义。\n⒏通，启发，使通～通。～导。～窍。～路先锋。\n⒐列举，列出～清单。计～。〈引〉逐个付出～支。～销。\n⒑清除，革除～除。\n⒒摆脱～脱。\n⒓沸，滚喝～水。汤～了。\n⒔分离，分配分～。离～。三七～。\n⒕写～处方。～收据。\n⒖扩大，发展～拓。～展。～源节流。\n⒗广阔，爽朗，乐观～阔。～朗。\n⒘用在动词后面，〈表〉效果走～。传～了。打～窗户。张～嘴巴。睁～眼睛。放～双手。\n⒙〈外〉黄金的纯度单位，二十四～为纯金。⒚热力学温度单位\"开尔文\"的简称，符号k。⒛","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-开"},{"id":"glyph-kai-5f02","script":"kai","character":"异","reading":"yì","description":"yì：(1)不同的～乎。～说。～常。～己（与自己意见不同或利害相冲突的人）。～端（旧时指不符合正统思想的主张或教义，如～～邪说”）。～化。～性。～样。大同小～。～曲同工。\n(2)分开离～。～居。\n(3)另外的，别的～日。～地。～国。～乡。～类。\n(4)特别的奇～。～闻。～彩。奇才～能（特殊的才能）。\n(5)奇怪惊～。诧～。怪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-异"},{"id":"glyph-kai-5f03","script":"kai","character":"弃","reading":"qì","description":"qì：舍去，扔掉抛～。遗～。～权。～市（古代在闹市执行死刑，并将尸体暴露街头）。～世（超出世俗或指去世）。～养（父母死亡的婉辞）。～置不顾。～瑕录用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弃"},{"id":"glyph-kai-5f04","script":"kai","character":"弄","reading":"nòng；lòng","description":"nòng：(1)玩耍，把玩摆～。玩～。～臣（帝王所亲近狎昵的臣子）。～潮儿。戏～。～瓦（瓦”是原始的纺锤，古代把它给女孩子玩，意为生女儿）。～璋（璋”是一种玉器，古代把它给男孩子玩。意为生儿子）。\n(2)做，干～假成真。～明白。\n(3)设法取得～点钱花。\n(4)搅扰这事～得人心惶惶。\n(5)耍，炫耀搔首～姿。\n(6)不正当地使用～权。～手段。捉～。\n(7)奏乐或乐曲的一段、一章～琴。梅花三～。\n(8)古代百戏乐舞中指扮演角色或表演节目。\nlòng：方言，小巷，胡同～堂。里～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弄"}];
